import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.CB_NIqHd.js";const u=JSON.parse(`{"title":"How would you start the investigation, what are your steps after the customer's feedback is that the application is really slow?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Web_Performance/How_would_you_start_the_investigation,_what_are_your_steps_after_the_customer's_feedback_is_that_the_application_is_really_slow.md","filePath":"senior_growth/Web_Performance/How_would_you_start_the_investigation,_what_are_your_steps_after_the_customer's_feedback_is_that_the_application_is_really_slow.md"}`),o={name:"senior_growth/Web_Performance/How_would_you_start_the_investigation,_what_are_your_steps_after_the_customer's_feedback_is_that_the_application_is_really_slow.md"};function s(n,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="how-would-you-start-the-investigation-what-are-your-steps-after-the-customer-s-feedback-is-that-the-application-is-really-slow" tabindex="-1">How would you start the investigation, what are your steps after the customer&#39;s feedback is that the application is really slow? <a class="header-anchor" href="#how-would-you-start-the-investigation-what-are-your-steps-after-the-customer-s-feedback-is-that-the-application-is-really-slow" aria-label="Permalink to “How would you start the investigation, what are your steps after the customer&#39;s feedback is that the application is really slow?”">​</a></h1><p>When users report that the app is slow, a senior developer must <strong>approach the issue systematically</strong> to identify whether the problem is <strong>frontend, backend, or network-related</strong>. Below is a structured investigation process and reasoning for each step.</p><hr><h2 id="🧭-1-collect-context-and-define-slow" tabindex="-1">🧭 1. <strong>Collect Context and Define “Slow”</strong> <a class="header-anchor" href="#🧭-1-collect-context-and-define-slow" aria-label="Permalink to “🧭 1. Collect Context and Define “Slow””">​</a></h2><p>Before touching code, clarify what “slow” means to the user:</p><ul><li>When does the slowdown occur? (initial load, after interaction, specific page)</li><li>How often and for whom? (all users, specific regions, browsers)</li><li>What devices or network conditions?</li><li>Are there logs or performance metrics available (e.g., Sentry, Datadog, New Relic)?</li></ul><blockquote><p>🎯 Goal: Narrow the scope. “Slow” can mean slow rendering, high network latency, or sluggish UI.</p></blockquote><hr><h2 id="🧩-2-reproduce-the-issue" tabindex="-1">🧩 2. <strong>Reproduce the Issue</strong> <a class="header-anchor" href="#🧩-2-reproduce-the-issue" aria-label="Permalink to “🧩 2. Reproduce the Issue”">​</a></h2><ul><li>Attempt to reproduce the issue under similar conditions (browser, network speed, device).</li><li>Use <strong>browser throttling</strong> (Network tab → Slow 3G) to simulate user experience.</li><li>Observe what part of the experience is lagging: <ul><li>Blank screen → likely large bundle or render-blocking script.</li><li>Late data → API latency.</li><li>Janky UI → inefficient rendering or heavy JavaScript.</li></ul></li></ul><hr><h2 id="🧠-3-gather-data" tabindex="-1">🧠 3. <strong>Gather Data</strong> <a class="header-anchor" href="#🧠-3-gather-data" aria-label="Permalink to “🧠 3. Gather Data”">​</a></h2><h3 id="🔹-browser-devtools" tabindex="-1">🔹 <strong>Browser DevTools</strong> <a class="header-anchor" href="#🔹-browser-devtools" aria-label="Permalink to “🔹 Browser DevTools”">​</a></h3><ul><li><strong>Performance Tab</strong> – Record a performance profile: <ul><li>Detect long tasks (&gt;50ms), layout thrashing, or re-renders.</li></ul></li><li><strong>Network Tab</strong> – Check: <ul><li>Waterfall chart for long requests.</li><li>Payload size, TTFB (Time To First Byte), caching headers.</li></ul></li><li><strong>Coverage Tab</strong> – Detect unused CSS/JS for possible tree shaking.</li><li><strong>Lighthouse / Web Vitals report</strong>: <ul><li>Current Core Web Vitals: LCP, INP and CLS. Use TTFB/TBT and relevant traces as diagnostics; FID/TTI are historical, and Lighthouse removed TTI in version10.</li></ul></li></ul><h3 id="🔹-backend-monitoring-if-applicable" tabindex="-1">🔹 <strong>Backend Monitoring (if applicable)</strong> <a class="header-anchor" href="#🔹-backend-monitoring-if-applicable" aria-label="Permalink to “🔹 Backend Monitoring (if applicable)”">​</a></h3><ul><li>Check API response times and server logs.</li><li>Profile database queries or caching (Redis, CDN, etc.).</li><li>Use APM tools (Datadog, New Relic) to locate bottlenecks.</li></ul><hr><h2 id="⚙️-4-identify-the-bottleneck" tabindex="-1">⚙️ 4. <strong>Identify the Bottleneck</strong> <a class="header-anchor" href="#⚙️-4-identify-the-bottleneck" aria-label="Permalink to “⚙️ 4. Identify the Bottleneck”">​</a></h2><p>Ask: <em>Where is the time being spent?</em></p><ul><li><strong>Network-bound:</strong> Slow APIs, no caching, large bundles → optimize APIs, enable CDN, compress assets.</li><li><strong>CPU-bound:</strong> Heavy JS parsing, large libraries, too many renders → code-splitting, memoization, virtualization.</li><li><strong>Render-bound:</strong> Too many DOM nodes or reflows → reduce complexity, debounce updates.</li></ul><hr><h2 id="🚀-5-optimize" tabindex="-1">🚀 5. <strong>Optimize</strong> <a class="header-anchor" href="#🚀-5-optimize" aria-label="Permalink to “🚀 5. Optimize”">​</a></h2><p>Based on findings:</p><ul><li><strong>Frontend load performance:</strong><ul><li>Implement <strong>code-splitting</strong>, <strong>lazy loading</strong>, <strong>tree-shaking</strong>, <strong>minification</strong>, <strong>preloading critical assets</strong>.</li><li>Optimize images (responsive sizes, WebP).</li></ul></li><li><strong>Backend / API performance:</strong><ul><li>Cache responses, paginate large datasets.</li><li>Optimize database queries.</li></ul></li><li><strong>UI performance:</strong><ul><li>Use React.memo, useCallback, useMemo.</li><li>Virtualize long lists (e.g., <code>react-window</code>).</li><li>Avoid unnecessary re-renders (e.g., by splitting components).</li></ul></li></ul><hr><h2 id="📈-6-measure-and-validate-improvements" tabindex="-1">📈 6. <strong>Measure and Validate Improvements</strong> <a class="header-anchor" href="#📈-6-measure-and-validate-improvements" aria-label="Permalink to “📈 6. Measure and Validate Improvements”">​</a></h2><p>After implementing changes:</p><ul><li>Re-run Lighthouse and DevTools audits.</li><li>Measure <strong>before vs. after</strong> for metrics like: <ul><li>TTFB/LCP/CLS, lab blocking/interaction traces, field INP and initial/total bytes as appropriate to the reported task.</li></ul></li><li>Validate perceived speed through user feedback.</li></ul><hr><h2 id="📋-summary-checklist" tabindex="-1">📋 Summary Checklist <a class="header-anchor" href="#📋-summary-checklist" aria-label="Permalink to “📋 Summary Checklist”">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th><th>Tools</th></tr></thead><tbody><tr><td>1. Gather info</td><td>Understand scope</td><td>Communication</td></tr><tr><td>2. Reproduce</td><td>Confirm issue</td><td>Browser/dev setup</td></tr><tr><td>3. Profile</td><td>Find bottlenecks</td><td>DevTools, Lighthouse, APM</td></tr><tr><td>4. Analyze</td><td>Identify cause</td><td>Network + JS profiling</td></tr><tr><td>5. Optimize</td><td>Implement fixes</td><td>Code-splitting, caching, etc.</td></tr><tr><td>6. Verify</td><td>Measure improvement</td><td>Lighthouse, Web Vitals</td></tr></tbody></table><hr><h3 id="hypothetical-investigation-not-measured-project-evidence" tabindex="-1">Hypothetical investigation, not measured project evidence <a class="header-anchor" href="#hypothetical-investigation-not-measured-project-evidence" aria-label="Permalink to “Hypothetical investigation, not measured project evidence”">​</a></h3><blockquote><p>Customer: “App loads really slowly on mobile.”</p></blockquote><ol><li>Reproduce on mobile throttling (3G, mid-range CPU).</li><li>DevTools → Network: 5 MB JS bundle.<br> → Hypothesis: initial JavaScript contributes; inspect request criticality, parse/evaluate tasks and interaction cost before calling it the root cause.</li><li>Apply <strong>code-splitting</strong> and <strong>lazy load non-critical components</strong>.</li><li>Illustrative values only: a candidate split might change initial bytes from5MB to1.5MB. Do not infer an8s→3.5s timing improvement from byte counts; define and measure a real loading/interaction outcome.</li></ol><hr><h3 id="📚-key-mindset" tabindex="-1">📚 Key Mindset <a class="header-anchor" href="#📚-key-mindset" aria-label="Permalink to “📚 Key Mindset”">​</a></h3><blockquote><p>As a senior developer, focus not just on fixing <em>symptoms</em> but building <em>monitoring and prevention systems</em>:</p></blockquote><ul><li>Integrate <strong>performance budgets</strong> in CI/CD.</li><li>Use <strong>Core Web Vitals monitoring</strong> (e.g., with Web Vitals library).</li><li>Regularly audit bundle sizes and dependencies.</li></ul><hr><p><strong>In summary:</strong></p><blockquote><p>Investigate → Measure → Identify → Optimize → Validate<br> Combine technical analysis with user perspective for lasting improvements.</p></blockquote><h2 id="an-evidence-ledger-for-one-reported-task" tabindex="-1">An evidence ledger for one reported task <a class="header-anchor" href="#an-evidence-ledger-for-one-reported-task" aria-label="Permalink to “An evidence ledger for one reported task”">​</a></h2><p>Record a release/artifact, route, dataset, device/browser, cache/network/CPU conditions and exact interaction. Keep a baseline trace plus several repeated runs; identify input delay, processing and presentation cost before selecting a fix. An empty screen can have server, CSS, font, hydration or application-error causes as well as bundle cost. Throttling is useful reproduction evidence, not a real-device equivalence guarantee.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Record</th><th>Reject this shortcut</th></tr></thead><tbody><tr><td>Observation</td><td>Exact slow task, affected cohort and trace marker</td><td>“The app is slow” as a diagnosis</td></tr><tr><td>Hypothesis</td><td>Owning stack/resource and mechanism</td><td>Large transfer alone proves CPU delay</td></tr><tr><td>Controlled change</td><td>One relevant change, same artifact/scenario controls</td><td>Different device/cache conditions compared</td></tr><tr><td>Result</td><td>Correctness plus repeated raw timings/variability, initial and feature-open behavior</td><td>A single Lighthouse score or invented percentage</td></tr><tr><td>Follow-up</td><td>Field collection/cohort/sample limits and regression budget</td><td>Lab TBT declared equal to field INP</td></tr></tbody></table><p>The <a href="./What_is_TTFI_(Time_to_first_interaction)._How_can_we_improve_TTFI.html">INP/TBT diagnostic lesson</a> defines current metric boundaries. The <a href="./What_are_some_general_practices_and_techniques_to_optimize_in_the_area_Explain_tree_shaking,_code_splitting_and_bundling,_minimizing,_data_caching..html#worked-production-analysis-module-contracts-before-chunk-tuning">production split/side-effects fixture</a> supplies actual synthetic build evidence, explicitly distinct from native user timing.</p><p><strong>Acceptance:</strong> investigate one slow task using this ledger, retain baseline/change traces and correct results, test failure/rapid input/focus, and explain one rejected hypothesis. Report unperformed field/native measurements as such; a written investigation is not a completed project performance result. References checked2026-10-22: <a href="https://web.dev/articles/inp" target="_blank" rel="noreferrer">INP</a>, <a href="https://developer.chrome.com/blog/lighthouse-10-0" target="_blank" rel="noreferrer">historical TTI removal</a>.</p>',47)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
